    const { MANEUVERS, FIGHTING_STYLES, METAMAGIC_OPTIONS, ELDRITCH_INVOCATIONS, TOTEM_SPIRITS, HUNTER_PREY_OPTIONS, DIVINE_ORDERS_2024, PRIMAL_ORDERS_2024, ELEMENTAL_TYPES, getManeuverById, getFightingStyleById, getMetamagicById, getInvocationById, getTotemSpiritById, getHunterPreyById } = __require('optionsCatalog.js');
